def link(u,s):return '<a href="'+E(u,quote=True)+'">'+E(s)+'</a>'
def ul(xs):return '<ul>'+''.join('<li>'+E(x)+'</li>'for x in xs)+'</ul>'
def section(h,*xs):return T.section(E(h),''.join(p(x)for x in xs))
